v2p_flat main(v_tree I)
{
    v2p_flat rsf_out = rsf_foliage_current(I);
    rsf_out.rsf_previous_clip = rsf_out.hpos;
    rsf_out.rsf_valid = 0;
    if (rsf_tree_history_valid())
    {
        rsf_out.rsf_previous_clip = rsf_foliage_previous(I).hpos;
        rsf_out.rsf_valid = 1;
    }
    return rsf_out;
}

